Pulled the relevant rules (destructive-nav-separation, destructive-emphasis, touch-target-size, safe-area-awareness, confirmation-dialogs, platform-adaptive). Key implementation decision: `Alert.prompt` is iOS-only, so a destructive, irreversible action like account deletion needs a custom cross-platform "type DELETE to confirm" modal as the second confirmation step rather than relying on native alerts alone. Here's the complete screen.

```tsx
// AccountSettingsScreen.tsx
// Deps: react-native, react-native-safe-area-context, react-native-vector-icons (Ionicons)
import React, { useCallback, useState } from 'react';
import {
  View,
  Text,
  Image,
  Pressable,
  ScrollView,
  Switch,
  Modal,
  TextInput,
  ActivityIndicator,
  Alert,
  StyleSheet,
  Platform,
  useColorScheme,
  KeyboardAvoidingView,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Ionicons from 'react-native-vector-icons/Ionicons';

// ---------- Types ----------

type IconName = string;

interface User {
  name: string;
  email: string;
  avatarUrl?: string;
}

interface AccountSettingsScreenProps {
  user?: User;
  onEditProfile?: () => void;
  onChangePassword?: () => void;
  onManageNotifications?: () => void;
  onOpenLanguage?: () => void;
  onOpenHelpCenter?: () => void;
  onOpenPrivacyPolicy?: () => void;
  onLogout?: () => void;
  onDeleteAccount: () => Promise<void>;
}

// ---------- Theme tokens ----------

function useColors() {
  const scheme = useColorScheme();
  const isDark = scheme === 'dark';
  return {
    isDark,
    background: isDark ? '#000000' : '#F2F2F7',
    surface: isDark ? '#1C1C1E' : '#FFFFFF',
    border: isDark ? '#38383A' : '#E5E5EA',
    textPrimary: isDark ? '#FFFFFF' : '#1C1C1E',
    textSecondary: isDark ? '#9A9A9E' : '#6D6D72',
    tint: '#3478F6',
    danger: '#FF3B30',
    overlay: 'rgba(0,0,0,0.5)',
    disabled: isDark ? '#48484A' : '#C7C7CC',
  };
}

type Colors = ReturnType<typeof useColors>;

// ---------- Reusable row ----------

interface SettingsRowProps {
  icon: IconName;
  label: string;
  colors: Colors;
  value?: string;
  onPress?: () => void;
  toggle?: { value: boolean; onValueChange: (next: boolean) => void };
  destructive?: boolean;
  isLast?: boolean;
  accessibilityHint?: string;
}

function SettingsRow({
  icon,
  label,
  colors,
  value,
  onPress,
  toggle,
  destructive,
  isLast,
  accessibilityHint,
}: SettingsRowProps) {
  const labelColor = destructive ? colors.danger : colors.textPrimary;
  const iconColor = destructive ? colors.danger : colors.tint;

  return (
    <Pressable
      onPress={onPress}
      disabled={!onPress && !toggle}
      android_ripple={{ color: colors.border }}
      accessibilityRole="button"
      accessibilityLabel={value ? `${label}, ${value}` : label}
      accessibilityHint={accessibilityHint}
      style={({ pressed }) => [
        styles.row,
        !isLast && { borderBottomWidth: 1, borderBottomColor: colors.border },
        pressed && Platform.OS === 'ios' && { backgroundColor: colors.border },
      ]}
    >
      <View style={[styles.iconWrap, { backgroundColor: destructive ? `${colors.danger}1A` : `${colors.tint}1A` }]}>
        <Ionicons name={icon} size={18} color={iconColor} />
      </View>

      <Text
        style={[styles.rowLabel, { color: labelColor }]}
        numberOfLines={1}
        accessible={false}
      >
        {label}
      </Text>

      <View style={styles.rowRight}>
        {value && !toggle && (
          <Text style={[styles.rowValue, { color: colors.textSecondary }]} numberOfLines={1}>
            {value}
          </Text>
        )}
        {toggle && (
          <Switch
            value={toggle.value}
            onValueChange={toggle.onValueChange}
            accessibilityLabel={label}
          />
        )}
        {onPress && !toggle && (
          <Ionicons name="chevron-forward" size={18} color={colors.textSecondary} style={{ marginLeft: 4 }} />
        )}
      </View>
    </Pressable>
  );
}

function SectionHeader({ title, colors }: { title: string; colors: Colors }) {
  return (
    <Text style={[styles.sectionHeader, { color: colors.textSecondary }]}>{title}</Text>
  );
}

function SectionCard({ children, colors }: { children: React.ReactNode; colors: Colors }) {
  return (
    <View style={[styles.sectionCard, { backgroundColor: colors.surface, borderColor: colors.border }]}>
      {children}
    </View>
  );
}

// ---------- Delete-account confirmation (two-step) ----------

const CONFIRMATION_PHRASE = 'DELETE';

interface DeleteConfirmSheetProps {
  visible: boolean;
  colors: Colors;
  onCancel: () => void;
  onConfirm: () => Promise<void>;
}

function DeleteConfirmSheet({ visible, colors, onCancel, onConfirm }: DeleteConfirmSheetProps) {
  const [inputText, setInputText] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isMatch = inputText.trim().toUpperCase() === CONFIRMATION_PHRASE;

  const handleClose = useCallback(() => {
    if (isSubmitting) return;
    setInputText('');
    setError(null);
    onCancel();
  }, [isSubmitting, onCancel]);

  const handleConfirm = useCallback(async () => {
    if (!isMatch || isSubmitting) return;
    setIsSubmitting(true);
    setError(null);
    try {
      await onConfirm();
      setInputText('');
    } catch (e) {
      setError('Something went wrong deleting your account. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  }, [isMatch, isSubmitting, onConfirm]);

  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={handleClose}
      accessibilityViewIsModal
    >
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
        style={[styles.modalOverlay, { backgroundColor: colors.overlay }]}
      >
        <Pressable style={StyleSheet.absoluteFill} onPress={handleClose} accessibilityElementsHidden />

        <View style={[styles.modalCard, { backgroundColor: colors.surface }]}>
          <View style={[styles.warningIconWrap, { backgroundColor: `${colors.danger}1A` }]}>
            <Ionicons name="warning-outline" size={28} color={colors.danger} />
          </View>

          <Text style={[styles.modalTitle, { color: colors.textPrimary }]}>
            Delete your account?
          </Text>
          <Text style={[styles.modalBody, { color: colors.textSecondary }]}>
            This permanently deletes your profile, data, and purchase history. This can't be undone.
            Type {CONFIRMATION_PHRASE} to confirm.
          </Text>

          <TextInput
            value={inputText}
            onChangeText={setInputText}
            placeholder={CONFIRMATION_PHRASE}
            placeholderTextColor={colors.textSecondary}
            autoCapitalize="characters"
            autoCorrect={false}
            autoFocus
            editable={!isSubmitting}
            returnKeyType="done"
            accessibilityLabel={`Type ${CONFIRMATION_PHRASE} to confirm account deletion`}
            style={[
              styles.modalInput,
              { borderColor: colors.border, color: colors.textPrimary },
            ]}
          />

          {error && (
            <Text
              style={[styles.modalError, { color: colors.danger }]}
              accessibilityLiveRegion="polite"
              role="alert"
            >
              {error}
            </Text>
          )}

          <View style={styles.modalActions}>
            <Pressable
              onPress={handleClose}
              disabled={isSubmitting}
              accessibilityRole="button"
              style={({ pressed }) => [
                styles.modalButton,
                { backgroundColor: colors.border },
                pressed && { opacity: 0.7 },
              ]}
            >
              <Text style={[styles.modalButtonText, { color: colors.textPrimary }]}>Cancel</Text>
            </Pressable>

            <Pressable
              onPress={handleConfirm}
              disabled={!isMatch || isSubmitting}
              accessibilityRole="button"
              accessibilityState={{ disabled: !isMatch || isSubmitting }}
              accessibilityHint="Permanently deletes your account"
              style={({ pressed }) => [
                styles.modalButton,
                { backgroundColor: isMatch ? colors.danger : colors.disabled },
                pressed && isMatch && { opacity: 0.85 },
              ]}
            >
              {isSubmitting ? (
                <ActivityIndicator color="#FFFFFF" />
              ) : (
                <Text style={[styles.modalButtonText, { color: '#FFFFFF' }]}>Delete Account</Text>
              )}
            </Pressable>
          </View>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

// ---------- Main screen ----------

export default function AccountSettingsScreen({
  user = { name: 'Jordan Rivera', email: 'jordan.rivera@example.com' },
  onEditProfile,
  onChangePassword,
  onManageNotifications,
  onOpenLanguage,
  onOpenHelpCenter,
  onOpenPrivacyPolicy,
  onLogout,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const colors = useColors();
  const insets = useSafeAreaInsets();
  const [pushEnabled, setPushEnabled] = useState(true);
  const [confirmSheetVisible, setConfirmSheetVisible] = useState(false);

  const initials = user.name
    .split(' ')
    .map((part) => part[0])
    .slice(0, 2)
    .join('')
    .toUpperCase();

  const handleDeletePress = useCallback(() => {
    Alert.alert(
      'Delete your account?',
      'This action is permanent and cannot be reversed. You will be asked to confirm again.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Continue',
          style: 'destructive',
          onPress: () => setConfirmSheetVisible(true),
        },
      ],
    );
  }, []);

  const handleFinalConfirm = useCallback(async () => {
    await onDeleteAccount();
    setConfirmSheetVisible(false);
  }, [onDeleteAccount]);

  return (
    <View style={[styles.screen, { backgroundColor: colors.background }]}>
      <ScrollView
        contentContainerStyle={[
          styles.content,
          { paddingTop: insets.top + 16, paddingBottom: insets.bottom + 32 },
        ]}
        contentInsetAdjustmentBehavior="automatic"
      >
        <Text style={[styles.screenTitle, { color: colors.textPrimary }]}>Account</Text>

        {/* Profile row */}
        <Pressable
          onPress={onEditProfile}
          accessibilityRole="button"
          accessibilityLabel={`${user.name}, ${user.email}`}
          accessibilityHint="Opens edit profile screen"
          style={({ pressed }) => [
            styles.profileCard,
            { backgroundColor: colors.surface, borderColor: colors.border },
            pressed && { opacity: 0.85 },
          ]}
        >
          {user.avatarUrl ? (
            <Image source={{ uri: user.avatarUrl }} style={styles.avatar} accessible={false} />
          ) : (
            <View style={[styles.avatar, styles.avatarFallback, { backgroundColor: colors.tint }]}>
              <Text style={styles.avatarInitials}>{initials}</Text>
            </View>
          )}
          <View style={styles.profileText}>
            <Text style={[styles.profileName, { color: colors.textPrimary }]} numberOfLines={1}>
              {user.name}
            </Text>
            <Text style={[styles.profileEmail, { color: colors.textSecondary }]} numberOfLines={1}>
              {user.email}
            </Text>
          </View>
          <Ionicons name="chevron-forward" size={18} color={colors.textSecondary} />
        </Pressable>

        {/* Account section */}
        <SectionHeader title="ACCOUNT" colors={colors} />
        <SectionCard colors={colors}>
          <SettingsRow
            icon="person-outline"
            label="Edit Profile"
            colors={colors}
            onPress={onEditProfile}
            accessibilityHint="Opens edit profile screen"
          />
          <SettingsRow
            icon="lock-closed-outline"
            label="Change Password"
            colors={colors}
            onPress={onChangePassword}
            accessibilityHint="Opens change password screen"
            isLast
          />
        </SectionCard>

        {/* Preferences section */}
        <SectionHeader title="PREFERENCES" colors={colors} />
        <SectionCard colors={colors}>
          <SettingsRow
            icon="notifications-outline"
            label="Push Notifications"
            colors={colors}
            toggle={{ value: pushEnabled, onValueChange: setPushEnabled }}
          />
          <SettingsRow
            icon="language-outline"
            label="Language"
            colors={colors}
            value="English"
            onPress={onOpenLanguage}
            accessibilityHint="Opens language selection screen"
            isLast
          />
        </SectionCard>

        {/* Support section */}
        <SectionHeader title="SUPPORT" colors={colors} />
        <SectionCard colors={colors}>
          <SettingsRow
            icon="help-circle-outline"
            label="Help Center"
            colors={colors}
            onPress={onOpenHelpCenter}
            accessibilityHint="Opens help center"
          />
          <SettingsRow
            icon="document-text-outline"
            label="Privacy Policy"
            colors={colors}
            onPress={onOpenPrivacyPolicy}
            accessibilityHint="Opens privacy policy"
          />
          <SettingsRow
            icon="log-out-outline"
            label="Log Out"
            colors={colors}
            onPress={onLogout}
            accessibilityHint="Signs you out of this device"
            isLast
          />
        </SectionCard>

        {/* Danger zone — spatially separated per destructive-nav-separation */}
        <SectionHeader title="DANGER ZONE" colors={colors} />
        <SectionCard colors={colors}>
          <SettingsRow
            icon="trash-outline"
            label="Delete Account"
            colors={colors}
            destructive
            onPress={handleDeletePress}
            accessibilityHint="Starts the permanent account deletion flow"
            isLast
          />
        </SectionCard>
      </ScrollView>

      <DeleteConfirmSheet
        visible={confirmSheetVisible}
        colors={colors}
        onCancel={() => setConfirmSheetVisible(false)}
        onConfirm={handleFinalConfirm}
      />
    </View>
  );
}

// ---------- Styles ----------

const styles = StyleSheet.create({
  screen: { flex: 1 },
  content: { paddingHorizontal: 16, maxWidth: 680, width: '100%', alignSelf: 'center' },
  screenTitle: { fontSize: 34, fontWeight: '700', marginBottom: 16 },

  profileCard: {
    flexDirection: 'row',
    alignItems: 'center',
    padding: 16,
    borderRadius: 12,
    borderWidth: 1,
    marginBottom: 24,
    minHeight: 48,
  },
  avatar: { width: 56, height: 56, borderRadius: 28 },
  avatarFallback: { alignItems: 'center', justifyContent: 'center' },
  avatarInitials: { color: '#FFFFFF', fontSize: 20, fontWeight: '600' },
  profileText: { flex: 1, marginLeft: 12, marginRight: 8 },
  profileName: { fontSize: 17, fontWeight: '600' },
  profileEmail: { fontSize: 14, marginTop: 2 },

  sectionHeader: {
    fontSize: 13,
    fontWeight: '600',
    letterSpacing: 0.4,
    marginBottom: 8,
    marginTop: 4,
    marginLeft: 4,
  },
  sectionCard: { borderRadius: 12, borderWidth: 1, overflow: 'hidden', marginBottom: 24 },

  row: {
    flexDirection: 'row',
    alignItems: 'center',
    minHeight: 52,
    paddingHorizontal: 16,
  },
  iconWrap: {
    width: 28,
    height: 28,
    borderRadius: 8,
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 12,
  },
  rowLabel: { flex: 1, fontSize: 16 },
  rowRight: { flexDirection: 'row', alignItems: 'center', marginLeft: 8 },
  rowValue: { fontSize: 15, maxWidth: 140 },

  modalOverlay: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: 24 },
  modalCard: { width: '100%', maxWidth: 400, borderRadius: 16, padding: 20, alignItems: 'center' },
  warningIconWrap: {
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: 12,
  },
  modalTitle: { fontSize: 18, fontWeight: '700', marginBottom: 8, textAlign: 'center' },
  modalBody: { fontSize: 14, textAlign: 'center', lineHeight: 20, marginBottom: 16 },
  modalInput: {
    width: '100%',
    borderWidth: 1,
    borderRadius: 10,
    paddingHorizontal: 14,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  modalError: { fontSize: 13, marginBottom: 8, textAlign: 'center' },
  modalActions: { flexDirection: 'row', gap: 12, marginTop: 8, width: '100%' },
  modalButton: {
    flex: 1,
    minHeight: 48,
    borderRadius: 10,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 12,
  },
  modalButtonText: { fontSize: 16, fontWeight: '600' },
});
```

Notes on the choices behind the implementation:

- **Delete flow is two steps**: a native `Alert.alert` (destructive style on iOS, works as a plain two-button dialog on Android) followed by a custom "type DELETE" modal. `Alert.prompt` only exists on iOS, so a custom modal is the only cross-platform way to add a typed-confirmation safeguard for an irreversible action.
- **Danger Zone is a separate section/card**, not just a red row in the middle of the list, per the destructive-action-separation guidance — reduces accidental taps.
- **Safe areas** are handled via `useSafeAreaInsets` rather than `SafeAreaView` so the scroll content, not just the screen edges, respects the notch/home-indicator.
- **Touch targets**: every row is `minHeight: 52` (exceeds 44pt iOS / 48dp Android), and the modal buttons are `minHeight: 48`.
- **Accessibility**: rows expose a single combined `accessibilityLabel` (label + value) and a `role=button`, navigation rows carry an `accessibilityHint`, the delete button exposes `accessibilityState.disabled`, and the inline error uses `accessibilityLiveRegion="polite"`.
- **Dark mode** uses `useColorScheme` with semantic tokens instead of hardcoded hex values scattered through JSX.
- Icons are vector (`Ionicons`), one consistent outline style — no emoji, no mixed filled/outline icons.

This assumes `react-native-safe-area-context` and `react-native-vector-icons` (or their Expo equivalents) are already in the project; swap `Ionicons` for `@expo/vector-icons/Ionicons` if the app is Expo-managed.
